from botforensics.cerber import cerber_verdicts, prepare_events, read_activity
from botforensics.geo import GeoLookup
from botforensics.privacy import Redactor

CSV = (
    '"Generated by:","WP Cerber Security 9.10"\n'
    '"Website:","Test"\n'
    '\n'
    '"Adresse IP","Date","Événement","Statut","Utilisateur local","Connexion de l\'utilisateur",'
    '"ID utilisateur","Nom d’utilisateur","Par utilisateur","Unix Timestamp","Request ID","URL"\n'
    '"203.0.113.9","x","Sous-réseau IP verrouillé","Tentative d’accès à une URL interdite",'
    '"","","0","","0","1792565433.8622","r1","site.example/wp-login.php"\n'
    '"203.0.113.9","x","Tentative d’accès à une URL interdite","Refusé","","","0","","0",'
    '"1792565433.8572","r1","site.example/wp-login.php"\n'
    '"198.51.100.4","x","Connecté","Code 2FA vérifié","Administration","adminuser","7",'
    '"adminuser","7","1792567157.8290","r2","site.example/secretadm/"\n'
    '"198.51.100.5","x","Envoi du formulaire refusé","","","","0","","0","1792567000.0","r3",""\n'
)


def _events(tmp_path):
    path = tmp_path / "activity.csv"
    path.write_text(CSV, encoding="utf-8")
    raw = read_activity(path)
    return raw, prepare_events(raw, "k", Redactor("site.example", "site.example", "secretadm"),
                               GeoLookup(None, None))


def test_read_activity_skips_preamble(tmp_path):
    raw, _ = _events(tmp_path)
    assert list(raw.columns) == ["ip", "event", "status", "username", "url", "timestamp"]
    assert len(raw) == 4
    assert str(raw["timestamp"].dt.tz) == "UTC"


def test_prepare_events_maps_groups_and_hides_secrets(tmp_path):
    _, ev = _events(tmp_path)
    assert list(ev["event_group"]) == ["locked", "malicious_request", "logged_in", "form_refused"]
    text = ev.to_csv()
    assert "203.0.113.9" not in text and "adminuser" not in text and "secretadm" not in text
    assert ev["username_hash"].iloc[2].startswith("user-")
    assert ev["url"].iloc[2] == "site.example/<custom-login>/"
    assert ev["url"].isna().iloc[3]


def test_verdict_takes_most_severe_event(tmp_path):
    _, ev = _events(tmp_path)
    v = cerber_verdicts(ev).set_index("ip_hash")
    locked_ip = ev["ip_hash"].iloc[0]
    assert v.loc[locked_ip, "cerber_verdict"] == "locked"
    assert v.loc[locked_ip, "cerber_events"] == 2
    assert set(v["cerber_verdict"]) == {"locked", "logged_in", "form_refused"}


def test_refused_login_attempt_is_a_login_failure():
    from botforensics.cerber import EVENT_GROUPS
    assert EVENT_GROUPS["tentative de connexion refusée"] == "login_failed"
